6	    public Set<Cell> nextGeneration(Set<Cell> livingCells) {
7	        Set<Cell> next = new LinkedHashSet<>();
8	        for (Cell cell : candidates(livingCells)) {
9	            if (isAliveNextGeneration(cell, livingCells)) {
10	                next.add(cell);
11	            }
12	        }
13	        return next;
14	    }
15	
16	    private boolean isAliveNextGeneration(Cell cell, Set<Cell> livingCells) {
17	        int livingNeighbours = countLivingNeighbours(cell, livingCells);
18	        return livingCells.contains(cell)
19	                ? survives(livingNeighbours)
20	                : isBorn(livingNeighbours);
21	    }
22	
23	    private Set<Cell> candidates(Set<Cell> livingCells) {
24	        Set<Cell> candidates = new LinkedHashSet<>(livingCells);
25	        for (Cell cell : livingCells) {
26	            candidates.addAll(cell.neighbours());
27	        }
28	        return candidates;
29	    }
30	
31	    private boolean survives(int livingNeighbours) {
32	        return livingNeighbours == 2 || livingNeighbours == 3;
33	    }
34	
35	    private boolean isBorn(int livingNeighbours) {
36	        return livingNeighbours == 3;
37	    }
38	
39	    private int countLivingNeighbours(Cell cell, Set<Cell> livingCells) {
40	        int count = 0;
41	        for (Cell neighbour : cell.neighbours()) {
42	            if (livingCells.contains(neighbour)) {
43	                count++;
44	            }
45	        }
46	        return count;
47	    }
48	}
